async function handleSlashBootstrap(sc: SlashContext): Promise<void> {
  const { ctx } = sc;
  // Scaffold the project's `.makestudio/` directory. Idempotent —
  // existing files are left alone, only missing pieces fill in.
  const { bootstrapProject } = require('../project-bootstrap');
  const root = ctx.activeProject?.localPath || ctx.cwd;
  const r = bootstrapProject(root);
  console.log();
  if (r.created.length > 0) {
    console.log(`  ${green('✓')} Scaffolded ${cyan(r.rootDir)}`);
    for (const p of r.created) console.log(`    ${dim('+')} ${p}`);
  } else {
    console.log(`  ${dim('Already scaffolded — nothing to create.')}`);
  }
  if (r.skipped.length > 0) {
    console.log(`  ${dim(`Kept ${r.skipped.length} existing file(s).`)}`);
  }
  console.log();
  console.log(`  ${dim('See')} ${cyan('.makestudio/README.md')} ${dim('for what each subfolder is for.')}`);
  console.log();
}

