async function handleSlashPlugin(sc: SlashContext): Promise<void> {
  const { rest } = sc;
  const sub = rest[0]?.toLowerCase();
  await withExitGuard(async () => {
    if (!sub || sub === 'list') {
      const { pluginListCommand } = require('../../commands/plugin');
      await pluginListCommand();
    } else if (sub === 'install' && rest[1]) {
      const { pluginInstallCommand } = require('../../commands/plugin');
      await pluginInstallCommand(rest[1]);
    } else if (sub === 'remove' && rest[1]) {
      const { pluginRemoveCommand } = require('../../commands/plugin');
      await pluginRemoveCommand(rest[1]);
    } else if (sub === 'enable' && rest[1]) {
      const { pluginEnableCommand } = require('../../commands/plugin');
      await pluginEnableCommand(rest[1]);
    } else if (sub === 'disable' && rest[1]) {
      const { pluginDisableCommand } = require('../../commands/plugin');
      await pluginDisableCommand(rest[1]);
    } else {
      console.log(`  ${dim('Uso:')} ${cyan('/plugin')} ${dim('[list|install|remove|enable|disable] [nome]')}`);
    }
  });
}

