async function handleSlashKanban(sc: SlashContext): Promise<void> {
  const { argsStr } = sc;
  await withDetachedRepl(async () => {
    const { pluginRegistry } = require('../../core/plugin-registry');
    const cmds = pluginRegistry.getCommands();
    const kanban = cmds.find((c: any) => c.name === 'kanban');
    if (kanban) {
      await kanban.handler(parseSlashArgs(argsStr));
    } else {
      console.log(`  ${yellow('!')} Plugin kanban nao instalado.`);
    }
  });
}


async function handleSlashMemstat(sc: SlashContext): Promise<void> {
  const { ctx } = sc;
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const dbg = require('../debug-log');
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const { tuiLog } = require('../tui/bridge');
  const snap = dbg.captureMemSnapshot({ ctx, trigger: 'manual' });
  const fmtMB = (b: number) => `${(b / 1024 / 1024).toFixed(1)}MB`;
  const lines: string[] = [];
  lines.push(bold('Process memory:'));
  lines.push(`  rss=${fmtMB(snap.rss)}  heapUsed=${fmtMB(snap.heapUsed)}  heapTotal=${fmtMB(snap.heapTotal)}  external=${fmtMB(snap.external)}  arrayBuffers=${fmtMB(snap.arrayBuffers)}`);
  lines.push(bold('Chat history:'));
  lines.push(`  ctx.messages: ${snap.ctxMessagesCount ?? '?'} entries (${fmtMB(snap.ctxMessagesBytes ?? 0)})`);
  lines.push(bold('TUI state:'));
  lines.push(`  tui.messages: ${snap.tuiMessagesCount ?? '?'} entries (${fmtMB(snap.tuiMessagesBytes ?? 0)})`);
  lines.push(`  pastedTexts: ${snap.pastedTextsCount ?? 0} entries (${fmtMB(snap.pastedTextsBytes ?? 0)})`);
  lines.push(bold('Listeners (subscribe-without-unsubscribe leak suspects):'));
  lines.push(`  messageHooks=${snap.messageHooks ?? 0}  pickerListeners=${snap.pickerListeners ?? 0}  toastListeners=${snap.toastListeners ?? 0}`);
  lines.push(`  permListeners=${snap.permListeners ?? 0}  usageListeners=${snap.usageListeners ?? 0}  transientSubs=${snap.transientSubs ?? 0}`);
  lines.push(`  stdin.data=${snap.stdinListeners ?? 0}  stdout.drain=${snap.stdoutListeners ?? 0}`);
  lines.push(bold('Caches:'));
  lines.push(`  ctx.readCache=${snap.readCacheCount ?? 0}  readPaths=${snap.readPathsCount ?? 0}`);
  lines.push(`  lsp: diagFiles=${snap.lspDiagnosticFiles ?? 0}  diagEntries=${snap.lspDiagnosticEntries ?? 0}`);
  lines.push(`  subagentPool=${snap.subagentPoolSize ?? 0}  coordinatorWorkers=${snap.coordinatorWorkers ?? 0}`);
  const args = sc.input.trim().split(/\s+/).slice(1);
  if (args.includes('--heap')) {
    const out = dbg.dbgHeapSnapshot('manual');
    if (out) lines.push(green(`  heap snapshot → ${out}`));
    else lines.push(red('  heap snapshot failed (debug log disabled? — run with --debug)'));
  } else {
    lines.push(dim('  hint: `/memstat --heap` writes a heapsnapshot file for Chrome DevTools'));
  }
  tuiLog(lines.join('\n'), 'info');
}

